def solve_n_queens(n):
    queens, res = [], []               # queens[r] = column of the queen in row r

    def safe(r, c):                    # scan every queen already placed
        return all(qc != c and abs(qc - c) != r - qr for qr, qc in enumerate(queens))

    def dfs(r):
        if r == n:
            res.append(['.' * c + 'Q' + '.' * (n - c - 1) for c in queens])
            return
        for c in range(n):
            if safe(r, c):
                queens.append(c)
                dfs(r + 1)
                queens.pop()

    dfs(0)
    return res

