def total_n_queens(n):
    cols, diag, anti = set(), set(), set()

    def dfs(r):
        if r == n:
            return 1
        count = 0
        for c in range(n):
            if c in cols or r - c in diag or r + c in anti:
                continue
            cols.add(c)
            diag.add(r - c)
            anti.add(r + c)
            count += dfs(r + 1)
            cols.remove(c)
            diag.remove(r - c)
            anti.remove(r + c)
        return count

    return dfs(0)

