def total_n_queens(n):
    full = (1 << n) - 1

    def dfs(cols, diag, anti):         # set bits = columns attacked in this row
        if cols == full:
            return 1
        count = 0
        free = full & ~(cols | diag | anti)
        while free:
            bit = free & -free         # lowest free column
            free ^= bit
            count += dfs(cols | bit, ((diag | bit) << 1) & full, (anti | bit) >> 1)
        return count

    return dfs(0, 0, 0)

